import sys, json
try:
    data = json.loads(sys.stdin.read())
except ValueError:
    raise SystemExit(1)
if not isinstance(data, dict):
    raise SystemExit(1)
if not isinstance(data.get("records"),list) or type(data.get("level")) is not int or any(not isinstance(r,dict) or not isinstance(r.get("name"),str) or type(r.get("level")) is not int for r in data["records"]):
    raise SystemExit(1)
def select_names(records,level):
    return [r["name"] for r in records if r["level"] == level]
print(json.dumps(select_names(data["records"],data["level"]),ensure_ascii=False))
